from grid import transpose


def test_square():
    assert transpose([[1, 2], [3, 4]]) == [[1, 3], [2, 4]]


def test_single_cell():
    assert transpose([[7]]) == [[7]]


def test_empty_table():
    assert transpose([]) == []


def test_square_three():
    assert transpose([[1, 2, 3], [4, 5, 6], [7, 8, 9]]) == [[1, 4, 7], [2, 5, 8], [3, 6, 9]]
